const META_PHONE_NUMBER_ID = 'YOUR_WHATSAPP_PHONE_NUMBER_ID';
const META_ACCESS_TOKEN = 'YOUR_META_PERMANENT_ACCESS_TOKEN';
const OFFICIAL_WAITLIST_TEMPLATE = 'dental_waitlist_offer';

const item = $input.first()?.json;
if (!item || !item.id) {
  return [];
}

let phone = String(item.phone || '').trim().replace(/^\+/, '');
if (phone.startsWith('01')) {
  phone = '20' + phone.slice(1);
}

const patientName = item.patient_name || 'عميلنا العزيز';
const doctorName = item.doctor_name || 'الطبيب المختص';
const cancelledDate = item.preferred_date;
const cancelledTime = item.preferred_time || '05:00 PM';

// الـ 4 متغيرات بنفس ترتيب قالب dental_waitlist_offer في ميتا بالظبط:
// {{1}}: اسم المريض | {{2}}: اسم الدكتور | {{3}}: التاريخ | {{4}}: الساعة
const templatePayload = {
  messaging_product: 'whatsapp',
  to: phone,
  type: 'template',
  template: {
    name: OFFICIAL_WAITLIST_TEMPLATE,
    language: { code: 'ar' },
    components: [
      {
        type: 'body',
        parameters: [
          { type: 'text', text: patientName },
          { type: 'text', text: doctorName },
          { type: 'text', text: cancelledDate },
          { type: 'text', text: cancelledTime }
        ]
      },
      {
        type: 'button',
        sub_type: 'quick_reply',
        index: '0',
        parameters: [{ type: 'payload', payload: 'CLAIM_WAITLIST' }]
      }
    ]
  }
};

return [{
  json: {
    waitlist_id: item.id,
    phone: phone,
    phone_number_id: META_PHONE_NUMBER_ID,
    meta_access_token: META_ACCESS_TOKEN,
    meta_payload: templatePayload
  }
}];

